syntax:
T object{}; // value-initialization using empty braces
T object(); // value-initialization with empty parentheses (note: in modern C++, this syntax is deprecated for value-initialization)
// For class types, value initialization invokes the default constructor if available
// For aggregate types, initializes members to their default values
// For built-in types, zero-initializes the object

code_example:
#include <iostream>
struct MyStruct {
    int a;
    MyStruct() { std::cout << "Default constructor called" << std::endl; }
};
int main() {
    MyStruct obj1{}; // value-initializes obj1, invokes default constructor
    int arr[3]{}; // value-initializes array elements to zero
    static int static_var{}; // zero-initialized at program startup
    return 0;
}
